begin;
do $cap$ begin if pg_database_size(current_database()) > 113970579 then raise exception 'Pretoria East expansion reached its 100 MB growth cap'; end if; end $cap$;
do $snapshot$ begin
  if exists (select 1 from public.places where id in ('clicks-menlyn-park', 'clicks-menlyn-maine', 'absolute-pets-menlyn-maine', 'absolute-pets-parkview')) then raise exception 'A new batch 07 ID already exists; recheck before import'; end if;
  if (select count(*) from public.places where group_id = 'absolute-pets' and category_id = 'shops' and is_active and source_checked_at = '2026-10-16' and ((id = 'absolute-pets-the-grove' and phone = '067 003 9358' and source_url = 'https://www.thegrovemall.co.za/the-grove-mall---stores') or (id = 'absolute-pets-woodlands' and phone = '010 023 0624' and source_url = 'https://woodlandsboulevard.co.za/shops'))) <> 2 then raise exception 'Existing pet-store evidence changed; recheck before updating'; end if;
